comms.text:
@1 אִלֵין מִנְיָנֵי מַשְׁכְּנָא מַשְׁכְּנָא דְסַהֲדוּתָא דִי אִתְמְנֵי עַל מֵימְרָא דְמשֶׁה פָּלְחַן לֵיוָאֵי בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@2 וּבְצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה עֲבַד יָת כָּל דִי פַקֵיד יְיָ יָת משֶׁה:
@3 וְעִמֵהּ אָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן נַגָר וָאֳמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא וּבִצְבַע זְהוֹרִי וּבְבוּצָא:
@4 כָּל דַהֲבָא דְאִתְעֲבֵד לְעִבִידָא בְּכֹל עִבִידַת קוּדְשָׁא וַהֲוָה דְהַב אֲרָמוּתָא עֶסְרִין וּתְשַׁע כִּכְּרִין וּשְׁבַע מְאָה וּתְלָתִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@5 וּכְסַף מִנְיָנֵי כְנִשְׁתָּא מְאָה כִכְּרִין וְאֶלֶף וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@6 תִּקְלָּא לְגֻלְגַלְתָּא פַלְגוּת סִלְעָא בְּסִלְעֵי קוּדְשָׁא לְכֹל דְעָבַר עַל מִנְיָנַיָא מִבַּר עֶסְרִין שְׁנִין וּלְעֵלָא לְשִׁית מְאָה וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין:
@7 וַהֲוָה מְאָה כִכְּרִין דִכְסַף לְאַתָּכָא יָת סַמְכֵי קוּדְשָׁא וְיָת סַמְכֵי דְפָרֻכְתָּא מְאָה סַמְכִין לִמְאָה כִכְּרִין כִּכְּרָא לְסַמְכָא:
@8 וְיָת אַלְפָא וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא עֲבַד וָוִין לְעַמוּדַיָא וְחִפָּא רֵישֵׁיהוֹן וְכַבֵּשׁ יָתְהוֹן:
@9 וּנְחָשָׁא דַאֲרָמוּתָא שִׁבְעִין כִּכְּרִין וּתְרֵין אַלְפִין וְאַרְבַּע מְאָה סִלְעִין:
@10 וַעֲבַד בַּהּ יָת סַמְכֵי תְּרַע מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִי לֵהּ וְיָת כָּל מָנֵי מַדְבְּחָא:
@11 וְיָת סַמְכֵי דְדַרְתָּא סְחוֹר סְחוֹר וְיָת סַמְכֵי תְּרַע דַרְתָּא וְיָת כָּל סִכֵּי מַשְׁכְּנָא וְיָת כָּל סִכֵּי דַרְתָּא סְחוֹר סְחוֹר:
@12 וּמִן תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עֲבָדוּ לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְּקוּדְשָׁא וַעֲבָדוּ יָת לְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@13 וַעֲבַד יַת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@14 וְרַדִידוּ יָת טַסֵי דַהֲבָא וְקַצִיצוּ חוּטִין לְמֶעְבַּד בְּגוֹ תִּכְלָא וּבְגוֹ אַרְגְוָנָא וּבְגוֹ צְבַע זְהוֹרִי וּבְגוֹ בוּצָא עוֹבַד אֳמָן:
@15 כַּתְפָּן עֲבָדוּ לֵהּ מְלַפְּפָן עַל תְּרֵין סִטְרוֹהִי יִתְלָפֵף:
@16 וְהֶמְיַן תִּקוּנֵהּ דִי עֲלוֹהִי מִנֵהּ הוּא כְּעוֹבָדוֹהִי דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@17 וַעֲבָדוּ יָת אַבְנֵי בוּרְלָא מְשַׁקְעָן מְרַמְצָן דִדְהָב גְלִיפָן כְּתַב מְפָרַשׁ עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@18 וְשַׁוִי יָתְהוֹן עַל כִּתְפָא דְאֵפוֹדָא אַבְנֵי דוּכְרָנָא לִבְנֵי יִשְׂרָאֵל כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@19 וַעֲבַד יָת חוּשְׁנָא עוֹבַד אֳמָן כְּעוֹבְדֵי אֵפוֹדָא דַהֲבָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@20 מְרַבַּע הֲוָה עֵיף עֲבָדוּ יָת חוּשְׁנָא זֶרְתָּא אֻרְכֵּהּ וְזֶרְתָּא פְתָיֵהּ עֵיף:
@21 וְאַשְׁלִימוּ בֵהּ אַרְבְּעָא סִדְרֵי אֶבֶן טָבָא סִדְרָא קַדְמָאָה סַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@22 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין שַׁבְזִיז וְסַבְהֲלוֹם:
@23 וְסִדְרָא תְּלִיתָאָה קַנְכֵּרֵי טַרְקְיָא וְעֵין עֶגְלָא:
@24 וְסִדְרָא רְבִיעָאָה כְּרוּם יַמָּא וּבוּרְלָא וּפַנְטֵּרֵי מְשַׁקְעָן מְרַמְצָן דִדְהַב בְּאַשְׁלָמוּתְהוֹן:
@25 וְאַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל אִנוּן תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ לִתְרֵין עֲסַר שִׁבְטִין:
@26 וַעֲבָדוּ עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@27 וַעֲבָדוּ תַּרְתֵּין מְרַמְצָן דִדְהַב וְתַרְתֵּין עִזְקָן דִדְהָב וִיהָבוּ יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@28 וִיהָבוּ תַּרְתֵּין גְדִילָתָא דִדְהַב עַל תַּרְתֵּין עִזְקָתָא עַל סִטְרֵי חוּשְׁנָא:
@29 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי יְהָבוּ עַל תַּרְתֵּין מְרַמְצָתָא וִיהָבֻנוּן עַל כַּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@30 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וְשַׁוִיאוּ עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָיו:
@31 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וִיהָבֻנוּן עַל תַּרְתֵּין כִּתְפֵי אֵפוֹדָא מִלְרַע מִלָקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@32 וְיַחֲדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקָתָא דְאֵפוֹדָא בְּחוּטָּא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@33 וַעֲבַד יָת מְעִילָא דְאֵפוֹדָא עוֹבַד מָחֵי גְמִיר תִּכְלָא:
@34 וּפוּם מְעִילָא כָּפִיל לְגַוֵהּ כְּפוּם שִׁרְיָן תּוֹרָא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר לָא יִתְבְּזָע:
@35 וַעֲבָדוּ עַל שִׁפּוֹלֵי מְעִילָא רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי שְׁזִיר:
@36 וַעֲבָדוּ זַגַיָא דְהַב דְכֵי וִיהָבוּ יָת זַגַיָא בְּגוֹ רִמוֹנַיָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר בְּגוֹ רִמוֹנַיָא:
@37 זַגָא וְרִמוֹנָא זַגָא וְרִמוֹנָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר לְשַׁמָשָׁא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@38 וַעֲבָדוּ יָת כִּתּוּנִין דְבוּצָא עוֹבַד מָחֵי לְאַהֲרֹן וִלִבְנוֹהִי:
@39 וְיָת מִצְנֶפְתָּא דְבוּצָא וְיָת שְׁבַח כּוֹבָעַיָא דְבוּצָא וְיָת מִכְנְסֵי בוּצָא דְבוּץ שְׁזִיר:
@40 וְיָת הֶמְיָנָא דְבוּץ שְּׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עוֹבַד צַיָר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@41 וַעֲבָדוּ יָת צִיצָא כְלִילָא דְקוּדְשָׁא דְהַב דְכֵי וּכְתָבוּ עֲלוֹהִי גְלִיפָן כְּתַב מְפָרַשׁ קֹדֶשׁ לַיְיָ:
@42 וִיהָבוּ עֲלוֹהִי חוּטָא תְכֶלְתָּא לְמִתַּן עַל מִצְנֶפְתָּא מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@43 וּשְׁלִים כָּל פָּלְחַן מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ:
@44 וְאַיְתִיוּ יָת מַשְׁכְּנָא לְמשֶׁה יָת מַשְׁכְּנָא וְיָת כָּל מָנוֹהִי פוּרְפוֹהִי דַפּוֹהִי עַבְּרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי:
@45 וְיָת חוֹפָאָה מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְיָת חוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@46 יָת אֲרוֹנָא דְסַהֲדוּתָא וְיָת אֲרִיחוֹהִי וְיָת כַּפֻּרְתָּא:
@47 יָת פָּתוֹרָא יָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@48 יָת מְנַרְתָּא דָכִיתָא יָת בּוֹצִינָהָא בּוֹצִנֵי סִדְרָא וְיָת כָּל מָנָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@49 וְיָת מַדְבְּחָא דְדַהֲבָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דִתְרַע מַשְׁכְּנָא:
@50 יָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@51 יָת סְרָדֵי דְדַרְתָּא יָת עַמוּדָהָא וְיָת סַמְכָהָא וְיָת פְּרָסָא לִתְרַע דַרְתָּא יָת אֲטוּנוֹהִי וְסִכָּהָא וְיָת כָּל מָנֵי פָּלְחַן מַשְׁכְּנָא לְמַשְׁכַּן זִמְנָא:
@52 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@53 כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל יָת כָּל פָּלְחָנָא:
@54 וַחֲזָא משֶׁה יָת כָּל עִבִדְתָּא וְהָא עֲבָדוּ יָתַהּ כְּמָא דִי פַקִיד יְיָ כֵּן עֲבָדוּ וּבָרִיךְ יָתְהוֹן משֶׁה:
@55 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@56 בְּיוֹמָא יַרְחָא קַדְמָאָה בְּחַד לְיַרְחָא תְּקִים יָת מַשְׁכְּנָא מַשְּׁכַּן זִמְנָא:
@57 וּתְשַׁוֵי תַמָן יַת אֲרוֹנָא דְסַהֲדוּתָא וְתַטֵּל עַל אֲרוֹנָא יָת פָּרֻכְתָּא:
@58 וְתָעֵל יָת פָּתוֹרָא וְתַסְדַר יָת סִדְרֵהּ וְתָעֵל יָת מְנַרְתָּא וְתַדְלֵק יָת בּוֹצִינָהָא:
@59 וְתִתֵּן יָת מַדְבְּחָא דְדַהֲבָא לִקְטֹּרֶת בּוּסְמַיָא קֳדָם אֲרוֹנָא דְסַהֲדוּתָא וּתְשַׁוֵי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@60 וְתִתֵּן יָת מַדְבְּחָא דַעֲלָתָא קֳדָם תְּרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא:
@61 וְתִתֵּן יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וְתִתֵּן תַּמָן מַיָא:
@62 וּתְשַׁוֵי יָת דַרְתָּא סְחוֹר סְחוֹר וְתִתֵּן יָת פְּרָסָא דִתְרַע דַרְתָּא:
@63 וְתִסַב יָת מִשְׁהָא דִרְבוּתָא וּתְרַבֵּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וּתְקַדֵשׁ יָתֵהּ וְיָת כָּל מָנוֹהִי וִיהֵי קוּדְשָׁא:
@64 וּתְרַבֵי יָת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל מָנוֹהִי וּתְקַדֵשׁ יָת מַדְבְּחָא וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשִׁין:
@65 וּתְרַבֵּי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ וּתְקַדֵשׁ יָתֵהּ:
@66 וּתְקָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@67 וְתַלְבֵּשׁ יָת אַהֲרֹן יָת לְבוּשֵׁי קוּדְשָׁא וּתְרַבֵּי יָתֵהּ וּתְקַדֵשׁ יָתֵהּ וִישַׁמֵשׁ קֳדָמָי:
@68 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשּׁ יָתְהוֹן כִּתּוּנִין:
@69 וּתְרַבִּי יָתְהוֹן כְּמָא דִי רַבִּיתָא יָת אֲבוּהוֹן וִישַׁמְשׁוּן קֳדָמָי וּתְהֵי לְמֶהֱוֵי לְּהוֹן רְבוּתְהוֹן לְכַהֲנוּת עֲלָם לְדָרֵיהוֹן:
@70 וַעֲבַד משֶׁה כְּכֹל דִי פַקִיד יְיָ יָתֵהּ כֵּן עֲבָד:
@71 וַהֲוָה בְּיַרְחָא קַדְמָאָה בְּשַׁתָּא תִנְיֵתָא בְּחַד לְיַרְחָא אִתָּקַם מַשְׁכְּנָא:
@72 וַאֲקֵם משֶׁה יָת מַשְׁכְּנָא וִיהַב יָת סַמְכוֹהִי וְשַׁוִי יָת דַפּוֹהִי וִיהַב יָת עַבְרוֹהִי וַאֲקֵם יָת עַמוּדוֹהִי:
@73 וּפְרַס יָת פְרָסָא עַל מַשְׁכְּנָא וְשַׁוִי יָת חוֹפָאָה דְמַשְׁכְּנָא עֲלוֹהִי מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@74 וּנְסִיב וִיהַב יָת סַהֲדוּתָא לַאֲרוֹנָא וְשַׁוִי יָת אֲרִיחַיָא עַל אֲרוֹנָא וִיהַב יָת כַּפֻּרְתָּא עַל אֲרוֹנָא מִלְעֵלָא:
@75 וְאָעֵלּ יָת אֲרוֹנָא לְמַשְׁכְּנָא וְשַׁוִי יָת פָּרֻכְתָּא דִפְרָסָא וְאַטֵל עַל אֲרוֹנָא דְסַהֲדוּתָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@76 וִיהַב יָת פָּתוֹרָא בְּמַשְׁכַּן זִמְנָא עַל צִדָא דְמַשְׁכְּנָא צִפוּנָא מִבָּרָא לְפָרֻכְתָּא:
@77 וְסַדַר עֲלוֹהִי סִדוּר דִלְחֵם קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@78 וְשַׁוִי יָת מְנַרְתָּא בְּמַשְׁכַּן זִמְנָא לָקֳבֵל פָּתוֹרָא עַל צִדָא דְמַשְׁכְּנָא לְדָרוֹמָא:
@79 וְאַדְלֵק בּוֹצִינָהָא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@80 וְשַׁוִי יָת מַדְבְּחָא דְדַהֲבָא בְּמַשְׁכַּן זִמְנָא קֳדָם פָּרֻכְתָּא:
@81 וְאַקְטַּר עֲלוֹהִי קְטֹרֶת בּוּסְמִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@82 וְשַׁוִי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@83 וְיָת מַדְבְּחָא דַעֲלָתָא שַׁוִי בִּתְרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וְאַסֵק עֲלוֹהִי יָת עֲלָתָא וְיָת מִנְחָתָּא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@84 וְשַׁוִי יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וִיהַב תַּמָן מַיָא לְקִדוּשׁ:
@85 וּמְקַדְשִׁין מִנֵהּ משֶׁה וְאַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן וְיָת רַגְלֵיהוֹן:
@86 בְּמֵעַלְהוֹן לְמַשְׁכַּן זִמְנָא וּבְמִקְרָבְהוֹן לְמַדְבְּחָא יְקַדְשׁוּן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@87 וַאֲקֵם יָת דַרְתָּא סְחוֹר סְחוֹר לְמַשְׁכְּנָא וּלְמַדְבְּחָא וִיהַב יָת פְּרָסָא דִתְרַע דַרְתָּא וְשֵׁיצֵי משֶׁה יָת עִבִידָא:
@88 וַחֲפָא עֲנָנָא יָת מַשְׁכַּן זִמְנָא וִיקָרָא דַיְיָ אִתְמְלֵי יָת מַשְׁכְּנָא:
@89 וְלָא יָכִיל משֶׁה לְמֵיעַל לְמַשְׁכַּן זִמְנָא אֲרֵי שְׁרָא עֲלוֹהִי עֲנָנָא וִיקָרָא דַיְיָ אִתְמְלִי יָת מַשְׁכְּנָא:
@90 וּבְאִסְתַּלָקוּת עֲנָנָא מֵעִלָוֵי מַשְׁכְּנָא נָטְלִין בְּנֵי יִשְׂרָאֵל בְּכֹל מַטְלָנֵיהוֹן:
@91 וְאִם לָא יִסְתַּלַק עֲנָנָא וְלָא נָטְלִין עַד יוֹמָא דְאִסְתַּלָקוּתֵהּ:
@92 אֲרֵי עֲנָנָא יְקָרָא דַיְיָ עַל מַשְׁכְּנָא בִּימָמָא וְחֵיזוּ אֶשָׁתָא הֲוֵי בְלֵילְיָא בֵּהּ לְעֵינֵי כָל בֵּית יִשְׂרָאֵל בְּכָל מַטְלָנֵיהוֹן: חזק:

@1 **אלה פקודי.** בפרשה זו נמנו כל משקלי נדבת המשכן, לכסף ולזהב ולנחשת, ונמנו כל כליו לכל עבודתו: **המשכן משכן.** שני פעמים, רמז למקדש שנתמשכן בשני חורבנין על עונותיהן של ישראל: **משכן העדת.** עדות לישראל שותר להם הקדוש ברוך הוא על מעשה העגל, שהרי השרה שכינתו ביניהם: **עבדת הלוים.** פקודי המשכן וכליו היא עבודה המסורה ללוים במדבר, לשאת ולהוריד להקים איש איש למשאו המפקד עליו, כמו שאמרו בפרשת נשא (במדבר ד) : **ביד איתמר.** הוא היה פקיד עליהם למסור לכל בית אב עבודה שעליו:
@2 **ובצלאל בן אורי** וגו' **עשה את כל אשר צוה ה' את משה.** אשר צוה משה אין כתיב כאן, אלא כל אשר צוה ה' את משה, אפלו דברים שלא אמר לו רבו, הסכימה דעתו למה שנאמר למשה בסיני, כי משה צוה לבצלאל לעשות תחלה כלים ואחר כך משכן, אמר לו בצלאל מנהג עולם לעשות תחלה בית ואחר כך משים כלים בתוכו. אמר לו כך שמעתי מפי הקדוש ברוך הוא. אמר לו משה בצל אל היית, כי בודאי כך צוה לי הקדוש ברוך הוא, וכן עשה המשכן תחלה ואחר כך עשה הכלים:
@4 **ככר.** ששים מנה, ומנה של קדש כפול היה, הרי הככר מאה ועשרים מנה, והמנה עשרים וחמשה סלעים, הרי ככר של קדש שלשת אלפים שקלים, לפיכך מנה בפרוטרוט כל השקלים שפחותין במנינם משלשת אלפים שאין מגיעין לככר:
@6 **בקע.** הוא שם משקל של מחצית השקל: **לשש מאות אלף** וגו' **.** כך היו ישראל, וכך עלה מנינם אחר שהוקם המשכן בספר במדבר. ואף עתה בנדבת המשכן כך היו. ומנין חצאי השקלים של שש מאות אלף עולה מאת ככר, כל אחד של שלשת אלפים שקלים, כיצד, שש מאות אלף חצאין הרי הן שלש מאות אלף שלמים, הרי מאת ככר, והשלשת אלפים וחמש מאות וחמשים חצאין עולין אלף ושבע מאות וחמשה ושבעים שקלים:
@7 **לצקת.** כתרגומו לאתכא: **את אדני הקדש.** של קרשי המשכן, שהם ארבעים ושמנה קרשים ולהם תשעים וששה אדנים, ואדני פרכת ארבעה, הרי מאה וכל שאר האדנים נחשת כתיב בהם:
@8 **וצפה ראשיהם.** של עמודים, מהן, שבכלן כתיב וצפה ראשיהם וחשוקיהם כסף.
@12 **ומן התכלת והארגמן** וגו' **.** שש לא נאמר כאן, ומכאן אני אומר, שאין בגדי שרד הללו בגדי כהנה, שבבגדי כהנה היה שש, אלא הם בגדים שמכסים בהם כלי הקדש בשעת סלוק מסעות, שלא היה בהם שש:
@14 **וירקעו.** כמו (תהלים קלו ו) לרוקע הארץ, כתרגומו ורדידו טסין היו מרדדין מן הזהב, אישטינדר''א בלעז , טסין דקין. כאן הוא מלמדך, היאך היו טווין את הזהב עם החוטין מרדדין הטסין דקין וקוצצין מהן פתילים לאורך הטס, לעשות אותן פתילים מעורבין עם כל מין ומין בחשן ואפוד שנאמר בהן זהב, חוט אחד של זהב עם ששה חוטין של תכלת, וכן עם כל מין ומין. שכל המינים חוטן כפול ששה, והזהב חוט שביעי עם כל אחד ואחד:
@39 **ואת פארי המגבעות.** תפארת המגבעות, המגבעות המפוארות:
@42 **לתת על המצנפת מלמעלה.** ועל ידי הפתילים היה מושיבו על המצנפת כמין כתר, ואי אפשר לומר הציץ על מצנפת שהרי בשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, והציץ היה נתון על המצח, הרי המצנפת למעלה והציץ למטה, ומהו על המצנפת מלמעלה, ועוד הקשיתי בה, כאן הוא אומר ויתנו עליו פתיל תכלת, ובענין הצואה הוא אומר (שמות כח לז) ושמת אותו על פתיל תכלת. ואומר אני פתיל תכלת זה חוטין הן לקשרו בהן במצנפת, לפי שהציץ אינו אלא מאוזן לאוזן, ובמה יקשרנו במצחו, והיו קבועין בו חוטי תכלת לשני ראשיו ובאמצעיתו, שבהן קושרו ותולהו במצנפת כשהוא בראשו, ושני חוטין היו בכל קצה וקצה אחד ממעל ואחד מתחת לצד מצחו, וכן באמצעו, שכך הוא נוח לקשור, ואין דרך קשירה בפחות משני חוטין, לכך נאמר (שמות כח לז) על פתיל תכלת, ועליו פתיל תכלת, וקשר ראשיהם השנים כלם יחד מאחוריו למול ערפו, ומושיבו על המצנפת. ואל תתמה שלא נאמר פתילי תכלת, הואיל ומרבין הן, שהרי מצינו בחשן ואפוד וירכסו את החשן וגו' בפתיל תכלת. ועל כרחך פחות משנים לא היו, שהרי בשתי קצות החשן היו שתי טבעות החשן, ובשתי כתפות האפוד היו שתי טבעות האפוד שכנגדן, ולפי דרך קשירה ארבע חוטין היו, ומכל מקום פחות משנים אי אפשר:
@43 **ויעשו בני ישראל.** את המלאכה ככל אשר צוה ה' וגו' :
@44 **ויביאו את המשכן** וגו' **.** שלא היו יכולין להקימו, ולפי שלא עשה משה שום מלאכה במשכן, הניח לו הקדוש ברוך הוא הקמתו, שלא היה יכול להקימו שום אדם מחמת כובד הקרשים, שאין כח באדם לזקפן, ומשה העמידו. אמר משה לפני הקדוש ברוך הוא איך אפשר הקמתו על ידי אדם, אמר לו עסוק אתה בידך נראה כמקימו, והוא נזקף וקם מאליו, וזהו שנאמר (שמות מ יז) הוקם המשכן, הוקם מאליו. מדרש רבי תנחומא:
@54 **ויברך אתם משה.** אמר להם יהי רצון שתשרה שכינה במעשה ידיכם, (תהלים צ יז) ויהי נעם ה' אלהינו עלינו ומעשה ידינו וגו' , והוא אחד מאחד עשר מזמורים שבתפלה למשה:
@57 **וסכת על הארן.** לשון הגנה, שהרי מחצה היתה:
@58 **וערכת את ערכו.** שתי מערכות של לחם הפנים:
@73 **ויפרש את האהל.** הן יריעות העזים:
@74 **את העדות.** הלוחות:
@76 **על ירך המשכן צפונה.** בחצי הצפוני של רוחב הבית: **ירך.** כתרגומו צדא, כירך הזה שהוא בצדו של אדם:
@81 **ויקטר עליו.** אהרן: **קטרת.** שחרית וערבית, כמו שנאמר (שמות ל ז) בבקר בבקר בהיטיבו את הנרות וגו' :
@83 **ויעל עליו** וגו' **.** אף ביום השמיני למלואים, שהוא יום הקמת המשכן, שמש משה והקריב קרבנות צבור, חוץ מאותן שנצטוו בו ביום, שנאמר (ויקרא ט ז) קרב אל המזבח וגו' : **את העלה.** עולת התמיד: **ואת המנחה.** מנחת נסכים של תמיד, כמו שנאמר (שמות כט מ) ועשרן סלת בלול בשמן וגו' :
@85 **ורחצו ממנו משה ואהרן ובניו.** יום שמיני למלואים הושוו כלם לכהנה, ותרגומו ומקדשין מניה, בו ביום קדש משה עמהם:
@86 **ובקרבתם.** כמו ובקרבם כשיקרבו:
@89 **ולא יכל משה לבוא אל אהל מועד.** וכתוב אחד אומר (במדבר ז פט) ובבא משה אל אהל מועד, בא הכתוב השלישי והכריע ביניהם, כי שכן עליו הענן, אמור מעתה כל זמן שהיה עליו הענן לא היה יכול לבא, נסתלק הענן נכנס ומדבר עמו:
@92 **לעיני כל בית ישראל בכל מסעיהם.** בכל מסע שהיו נוסעים היה הענן שוכן במקום אשר יחנו שם. מקום חניתן אף הוא קרוי מסע, וכן (בראשית יג ג) וילך למסעיו, וכן (במדבר לג א) אלה מסעי לפי שממקום החניה חזרו ונסעו, לכך נקראו כלן מסעות:

@1 **אלה פקודי וגו'**. אומרו **אלה** לפסול כל מנינים שבעולם כי כל מה שימנה אדם מקנינים המדומים אין מניינו מנין ושמו מורה עליו מה אתה מונה, אבל מנין זה עומד לעולם, והטעם להיות מנין המשכן המופלא אשר שכן שם אלהי עולם ה':
@1 **עוד** ירצה על דרך אומרם ז''ל (ב''מ מ''ב.) אין ברכה שורה לא בדבר הספור ולא בדבר המנוי, וכאן אמר **אלה פקודי** פירוש לאלה יש מנין ואין הקפדה כי מנין זה אדרבא מניינו תביא הברכה כי כל פרט שירבה במספר תגדיל הזכות ותסובב הברכה למרבה, והטעם להיותו של המשכן:
@1 **עוד** ירמוז באומרו **אלה** על דרך אומרם ז''ל (ויק''ר פכ''א) אם עשית חבילות וכו' עשה כנגדן חבילות של מצות, כי צריך האדם לתקן החטא בדוגמא, והנה ישראל חטאו ואמרו (לעיל ל''ב ד') אלה אלהיך לזה באה **אלה** זאת בבחינת הזכות לכפרת עון זה, ותמצא כי אמרו (רבה) העדות שעדות הוא להם שנתכפר עון העגל, וכשתדקדק תמצא כי כל פרטי עון העגל בא כנגדן במשכן, הם התאוו תאוה (ל''ב א') אלהים אשר ילכו לפניהם הנה הנם הכינו מקום לה' אלהים אמת להיות לפניהם, הם בנו מזבח והעלו עולות (שם ו') הנה הנם הכינו מזבח להעלות עולות ושלמים לה', הם נתנו זהבם הנה הנם נתנו זהבם וכספם וכל כלי חמדתם לה', הם פרקו נזמיהם הנה הנם הביאו האנשים על הנשים לא נזם לבד אלא כל עדים מעליהם וכל כלי חמדה, וכמו שפירשנו בפרשת ויקהל (ל''ה כ''ב) הם עשו ממונים עליו לעשותו הנה הנם פקדו בצלאל לעשות וכו', אמרו אלה אלהיך הנה **אלה פקודי** לכפרה:
@1 **עוד** ירצה על זה הדרך להיות שמשה עשה המספר לישראל המובא בית ה', לזה באה התורה והצדיקתו ואמרה **אלה פקודי** וגו', פירוש על דרך אומרו (ויקרא כ''ג ב') אלה הם מועדי, מה הוא המספר שה' מצדיק אשר פוקד על פי משה דקדק לומר **על פי משה** ולא אמר אשר פקד משה, הטעם כי לא היה הזולת עמו להצטדק אלא מפיו אנו חיין שכן כתיב (ל''ו ג') ויקחו מלפני משה שהוא לבדו לקח הכל, וטעמו של משה שהביא עצמו לידי חשד, אולי שלא עלה בדעתו חשד זה להשמר ממנו כי איך יחשדו אותו וה' מדבר עמו בכל עת אם ח''ו ימצא בו עול ימאסנו אלוה היודע נסתרות, ואין צריך לומר שלא ידבר אתו עוד אלהים, או דקדק מאמר ה' שאמר לו (ריש פ' תרומה) דבר אל בני ישראל ויקחו לי וגו' כמו שפירשנוה במקומה כי צוה לו להיות הוא גזבר לבדו, וישרים דרכי ה' וצדיקים ילכו בם אף על פי שפושעים יכשלו בם:
@1 **עוד** ירצה על זה הדרך **אלה פקודי המשכן** ומי יצדיק שכן הוא ולא יותר, לזה אמר משכן העדות פירוש המשכן הוא יעיד על הדבר על דרך אומרם ז''ל (שמו''ר פנ''ב) בפסוק ויקם משה את המשכן שלא היה אחד מישראל יכול להעמידו, וזה לשונם כמה חכמים היו שם ולא היו יכולין להקים את המשכן וכו' ולא היו יודעים לישב אותו כל אחד נטל מלאכתו והלך אצל משה וכו' ושרתה רוח הקודש על משה והקים את המשכן ע''כ, זה הוא עדותו היותו נקי כפים שאין חמס בכפיו שאין הקב''ה עושה נס לעושי עול ובפרט במקום עצמו שנעשה בו העול ח''ו, ואם תאמר ומה עדות הוא זו יש לתלות כי לצד כי משה היה גבור חיל גבורתו עמדה לו שהעמידו מה שלא היה כח כמו כן בזולתו, לזה גמר אומר **עבודת הלוים ביד איתמר** וגו', פירוש הלא תמצא שעבודת הלוים שהיא ביד איתמר היא קרשי המשכן ובריחיו ועמודיו ואדניו והם המורידים אותו בנסעם ומקימין אותו בחנותם דכתיב בפרשת במדבר (א' נ''א) ובחנות המשכן יקימו אותו הלוים הרי שהלוים היו מפרקין ומקימין אותו אם כן לא מניעת הכח היא הסיבה; וכפי זה הרווחנו כוונת אומרו **עבודת הלוים** וגו' **ביד איתמר** שאין ידוע מה בא ללמד ומה שייכות למאמר זה כאן ולמה לא אמר אלא איתמר ולא אלעזר הגדול, ולדרכינו יבא על נכון, ועדיין יש לתלות לצד החכמה כי משה חכם וחריף היה וידע להקימו ולעולם לא נעשו מעשה נסים, לזה אמר **ובצלאל בן אורי** וגו' **עשה את כל אשר צוה ה'** ואמרו ז''ל שאפילו דברים שלא אמר לו משה הסכימה דעתו, **ואתו אהליאב** וגו' **חרש** וגו' ואף על פי כן לא עמדה לו חכמתו וכאומרם במדרש (שמו''ר פנ''ב) שגם אומנות האומנים לא הועילה, וכפי זה הרווחנו כוונת הכתוב בהודעת מעשה בצלאל אחר שכבר ידענו זה פעמים ושלש בפרשת ויקהל אלא בא לחזק עדות נס המשכן לומר הא למדת שאין זה אלא נס וזו הוא עדות המשכן על פקודיו, ולדרך זה אומרו **אשר פוקד על פי משה** לומר שעל זה באה העדות להסיר החשד ממנו:
@1 **עוד** ירצה על דרך אומרם ז''ל (שם פנ''א) שהמשכן היה כפרה על מעשה העגל, עוד אמרו בחולין (ה'.) כי שקולה עבודה זרה ככל התורה כולה, והוא אומרו אלה פקודי פירוש על דרך שתרגם אונקלוס (ויקרא כ''ז ל''ד) אלה המצות אלין פקודיא, המצות שתלוים במשכן **משכן העדות אשר פוקד** וגו' פירוש כל המצות שבתורה שנצטווה משה כולם ישנם במצות המשכן, ובזה יכפר המשכן על העגל ששקול כנגד כל התורה, ואולי שנתכוון לרמוז הענין בחשבון פקודי המשכן שעולה תרי''ה והם תרי''ג מצות וב' הלוחות, ומעתה אלה תשכחנה כי נתקן בפקודי המשכן, ואומרו **עבודת הלוים** בא לשמור את הדבר לבל תאמר כיון שנתכפר עון העגל אשר הוא יסובב הסרת עבודה מהבכורות כמאמרם ז''ל (במ''ר פי''ב) אם כן תחזור העטרה ליושנה ויעבדו הבכורות עבודת המשכן, לזה אמר סמוך לדבר **עבודת הלוים** פירוש עבודה זו אינה אלא ללוים, כאן כלל כל שבט לוי בין הכהנים בין הלוים כי גם הכהנים יקראו לוים דכתיב (דברים כ''ז ט') והכהנים הלוים, ואומרו **ביד איתמר** וגו' פירוש לא מבעיא עבודות המעולות של הכהנים ולא מבעיא עבודות הלוים המעולות של בני קהת ובני גרשון אלא אפילו עבודה הקלה של הלוים **ביד איתמר** שהם הקרשים והאדנים הדבר במקומו עומד, ומזה אתה למד כי לא נמחק עון העגל מחק שאין רשומו ניכר והעד הנאמן (לעיל ל''ב ל''ד) וביום פקדי וגו':
@1 **עוד** ירמוז באומרו **פקודי המשכן** לשון מינוי על דרך אומרו (במדבר ד' ט''ז) ופקודת אלעזר שהוא לשון מינוי על הדבר, והודיע הכתוב כל מינויי המשכן מהם ממונים על המשכן עצמו להתקיים או להתבטל ח''ו, ומהם על עבודתו, ומהם על עובדיו, ומהם על מלאכתו, והתחיל במינוי קיום המשכן ואמר **משכן העדות** פירוש פקודת המשכן הוא העדות שהיא התורה כי כל זמן שישראל עוסקים בתורה ומקיימין מצותיה יתקיים המשכן וזולת זה אין משכן, והוא אומרם ז''ל (במד''ר ל''ב) בפסוק (תהלים ע''ח) אוהל שכן באדם וכי באדם שכן אהלו אלא באמצעות אדם אם יכינו לבם ללמוד תורה ולקיים מצותיה, ולאו דוקא עדות הכתובה בלוחות ובספר כתובה אלא **אשר פוקד על פי משה** פירוש תורה שבעל פה שנמסרה למשה לפה ולא לכותבה, ב' יכוין על פקודת משה שפקיד הוא בדבר זה לצוות משפטיו ודיניו של משכן, מינוי ג' הם העובדים במשכן עבודת הלוים פירוש הם ממונים על עבודת המשכן, מינוי ד' הם אהרן ובניו ושלשתם רמזם הכתוב **איתמר ואהרן** הרי נאמרו בפירוש ואלעזר רמזו באומרו **בן אהרן** כי אני יודע כי איתמר בנו של אהרן הוא אלא לרמוז על אלעזר, ואולי שלא הזכירה התורה אהרן כל עיקר במינוי המשכן אלא בניו ואומרו **בן אהרן הכהן** יכוין אל אלעזר ולא הזכיר אהרן לצד שעדיין חסר תיקון מעשה העגל שעשה כי אחרי כן מתו ב' בניו והביא כפרתו ביום ח' למילואים אשר על כן לא הזכיר פקודתו אלא הזכיר שמו עם בנו, מינוי ה' הוא העושה מלאכת המשכן והוא שאמר **ובצלאל** וגו' **עשה** וגו' **ואתו אהליאב** וגו' נמצאת אומר שהממונים בפרט זה של המשכן הם ה', א' התורה היא מושלת על קיומו אם יתקיים אם לאו, ב' משה ממונה על מצותו באיזה אופן יעשה ויתנהג, ג' הלוים לעבוד לפרוק ולטעון וכו', ד' הכהנים לעבוד העבודות ולהתמנות על הלוים בעבודתם, ה' ובצלאל ואהליאב על המלאכה ועל אלה אמר **אלה פקודי המשכן**:
@4 **כל הזהב העשוי וגו'**. צריך לדעת גזירת הכתוב איה מקומה, ואם אומרו תשע ועשרים ככר אם כן למה חזר לומר **ויהי זהב** וגו', ואולי כי גזירת הכתוב הוא **בכל מלאכת הקודש** וכוונת הכתוב היא לומר שכל הזהב העשוי למלאכה לא נחסר ולא נפשע ולא נגנב ממנו דבר אלא הכל נכנם בכל מלאכת הקודש, ובזה הוציא האומנים העושים במלאכה מהחשד.
@4 **עוד** ירצה להודיע נסים שנעשו בזהב המשכן כי דבר ידוע הוא כי בעשות האדם כלי מזהב או משאר המתכות על כל פנים יתמעט משיעור משקל הזהב שנעשה ממנו הכלי ולא יעמוד הכלי במשקל הראשון לצד ההתחלקות ופעולות המלאכותיו ומה גם כשיהיה במלאכה ריבוי התחלקות וחלקים דקים פשיטא שיתמעט באמצעות כן, ועוד בהכין האדם מעשה המלאכה כמו שתאמר שתי וערב לארוג בגד פתילי זהב לעשות מהם המלאכה מן הנמנע שידקדק במוכן לא פחות ולא יותר וכאן הודיע הכתוב שנעשה נס שכל הזהב העשוי למלאכה היה **בכל מלאכת הקודש**, מאומרו **כל** הודיעך. שלא נתמעט מאמצעות המלאכה כנזכר, ומאומרו **העשוי** רשם גם כן שכל המוכן למלאכה לא נותר ממנו דבר לבטלה והכל נכנס בכל מלאכת הקודש, ודקדק לומר **בכל** ולא אמר במלאכת הקודש נתכוין לומר גם כן שהספיק העשוי לכל, וזה הוא עיקר הנס שזולת זה אין נם במה שלא הותיר כי אפשר ששיער שיעור שודאי לא יותיר ולא הוכר הנם אלא באמצעות שלא הותיר ולא החסיר:
@8 **ואת האלף ושבע וגו** '. פירוש הנשארים, ורבותינו ז''ל אמרו (שמו''ר פנ''א) ששכחם וכשזכר אותם אמר ואת האלף וגו' הם ממה שעשה ווים וגו', והנה להסוברים מהחכמים (ראב''ע) כי לא היה כסף בנדבת המשכן זולת מחצית השקל יתבאר אומרו **ואת האלף** על זה הדרך לפי שמצינו שצוה ה' בתרומת הכסף מחצית השקל ובכל מלאכת המשכן לא מצינו שצוה ה' מעשה כסף זולת האדנים והווין וחשוקיהם וביאר באדנים שצריך ככר לאדן והווין לא הודיע ה' שיעורן ושיעור חשוקיהן, לזה נתחכם בצלאל וחלק הנשאר מהאדנים ועשאן ווין שהגם שלא צוה ה' שיעורן ממה שנתן שיעור לאדנים השכילו כי הווין וחשוקיהם יהיו מהנשאר, ולזה אמר **ואת האלף** וגו' **עשה ווין** פירוש שחלק הסך לווין, ואין הכי נמי אם היה נשאר יותר או פחות היה מחלק הנשאר, ואם היה אומר הכתוב ויעש ווין וגו' יהיה נשמע כי נאמר מפי אל עליון שיעור זה ולא כן הוא אלא מכללן של דברים הבין כנזכר, ודעתי אינה כסברא זו כי ודאי כי כסף אחר היה בתרומת המשכן מלבד הבקע לגלגולת כי מקרא מלא דבר הכתוב בויקהל (ל''ה כ''ד) כל מרים תרומת כסף ונחושת ובפסוק זה לא יצדיקו דברי ראב''ע שיישב בפסוק (כ''ה ג') וזאת התרומה והמשכיל יבין, ויתבאר אומרו **ואת האלף** על דרך מה שפירשנו בפסוק (כ''ד) כל הזהב וגו' פירוש שלא נחסר באמצעות ההתכה ופרטי המלאכה שהגם שעשה כמה פרטי מלאכה במעשה כמה ווין וחשוקיהן אף על פי כן המספר עצמו בשלימות היה בווין ולא נחסר ממנו כלום והוא אומרו **ואת האלף** וגו' **עשה ווין** והבן:
@12 **כאשר צוה ה' את משה**. טעם אומרו כן בכל פרט ופרט, על פי מה שכתבנו בפרשת תצוה (כ''ז כ') כי חלק ה' למשה חלק בכל מלאכות ועבודות הנעשות במשכן כי חלקו במעשה הוא המצוה אשר יצוה ה' הדבר על ידו לזה מזכירו בכל פרט ופרט שהגם שאינו עושה הרי הוא מצוה לעשות.
@12 **עוד** ירצה שהיו אומרים בשעת המלאכה הרי אנו עושים דבר זה **כאשר צוה ה' את משה**.
@12 **עוד** נראה לפי מה שקדם לנו כי אין לך מצוה שאין בה פרטי ההשכלה ולא נכתב בתורה אלא מיעוט כמאמר ר' יוחנן בהניזקין (גיטין ס':) ומלבד זה יש בכל מעשה ממעשה המשכן מושכל, והוא פנימיות הדברים ואלה יעשו בכוונת הלב ובשכליות הנעלם ויעשו דבר במינו כידוע ליודעי דעת והבנין, והוא מה שרמזה התורה בכל פרט ופרט **כאשר צוה ה' את משה** פירוש בעל פה ואינו מפורש בתורה לצד יקרת הדבר, ואשכילך כי המכתב הוא מבחינת המופעל והמושכל מושלל מהתקבל מקצתו בבחינת ההפעל ומקצתו גם מבחינת הנדבר כי רחוק הוא בב' הדרגות, וקצת רמז ה' בנפעל נראה ואינו נראה בסוד צורת האותיות וטעמיהם ועטרות שעל ראשיהם התגין ומעשיהם בחינת מחשבה יקראו ונגלה למשה בסיני פלאי פלאות, וצא ולמד מדרשת ר' עקיבא (סנהדרין ק''ו) ג' מאות הלכות בעליונו של למ''ד, המה ראו מעשה ה', והודיע הכתוב בכל פרטי המשכן כי עשאוהו **כאשר צוה ה' את משה** ככל נפלאות אשר יכוין עליהם:
@35 **על שולי וגו'**. מכאן אני מדייק שהאמת הוא כהסוברים שהפעמונים הם בשורה עם הרמונים ולא בתוכם ממש שהרי הקדים הכתוב נתינת הרמונים על שולי המעיל ואחר כך אמר מעשה הפעמונים בפני עצמן ויתנו אותם תוך הרמונים ומעתה אם הפעמון תוך הרימון ממש למה הוצרך הכתוב לומר על שולי אחר שכבר קדם ואמר שהרמונים הם על שולי המעיל זה בזה תלוי, ותמה אני על רמב''ן שפנה מדרך זה, ומה שיישב שלא נתן הרימון במעיל עד שנתן בתוכו הפעמון הכתוב יגיד הפך זה, וממה שאמר כי לזה כפל לומר בתוך הרמונים פעמים, קשה למה הקדים הכתוב לצוות שיתן הרמונים על שולי המעיל קודם שיעשה הפעמונים ויצטרך לחזור לומר פעמים בתוך הרמונים לרבות שיתנם קודם, ופשוט הוא שהרב לא דק יפה כמנהג זכות עיונו הקדוש:
@36 **בתו** ך **הרמונים**. טעם שכפל לומר כן, לומר שיהיו מכוונים הפעמונים כנגד הרמונים שלא יהיה הפעמון משוך לצד מטה או לצד מעלה אלא גופו של פעמון לפני הרימון ועומד בשורה לא למעלה ולא למטה, ודבר זה אינו מתחייב מאומרו פעם ראשונה הפעמונים בתוך הרימונים כי זה בא לשלול שלא יהיו הרימונים בתוך הפעמונים על זה האופן תתחיל השורה בפעמון ולפניו רימון כפי זה יהיו הרמונים בתוך הפעמונים כי המעיל לא היה מחובר מלמטה סביב לומר שתמיד יהיו אלו תוך אלו כל שיהיו שוים במספר אלא מחולק היה לב', ולזה תמצא שלא עשה בברייתא מספר הרימונים כפעמונים כי הם יותר מהם:
@37 **פעמון ורימון**. הוצרך לכתוב זה שלא תבין שיכול לעשות ב' או ג' פעמונים בתוך ב' או ג' רימונים וקורא אני בהם בתוך הרימונים, לזה אמר **פעמון ורימוז**, פירוש שלא יעשה ב' פעמונים ורימון, וחזר לומר **פעמון ורימון** בא לשלול שלא יעשה ב' רימונים לכל פעמון ויהיה כל פעמון בב' רימונים ולא תעלה רימון שבימינו של פעמון זה לשמאלו של פעמון הבא אחריו, לזה אמר פעם ב' **פעמון ורימון** פירוש סמוך לרימון של פעמון ראשון יהיה פעמון ב' והבן:
@43 **ותכל כל עבודת וגו'**. פירוש לא הם כילו שאם היה ה' מצוה עוד בעבודתו יתברך יעשו בני ישראל בכל אות נפשם אלא שכלתה המלאכה אשר צוה ה':
@43 **עוד** ירצה באומרו **ותכל** לצד שהיה בה מלאכות שנעשו מעצמן שהיא מנורה שאמרו ז''ל (במד''ר פט''ו) שנעשית מעצמה לזה לא כינה הכל עליהם כי יש חלק במלאכה שהוא לא נעשה אלא הכאה בקורנם והיא מעצמה כלתה.
@43 **עוד** ירמוז על דרך אומרו (תהלים פ''ד) נכספה וגם כלתה נפשי לחצרות ה', כי עשו כל העבודה חשוקה וכלילת יופי:
@43 **ויעשו בני ישראל וגו'**. והגם שלא עשה אלא בצלאל וחכמי לב, שלוחו של אדם כמותו וכאילו כל ישראל עשו, והגם שלא מצינו שעשה בצלאל אלא במאמר ה' ולא הם שלחוהו, אף על פי כן הרי הסכימו עליו:
@43 **עוד** נראה כי כאן עשה הכתוב מחברת הכללות בקיום התורה והראה כי בני ישראל יזכו זה לזה והתורה נתנה להתקיים בכללות ישראל כל אחד יעשה היכולת שבידו ויזכו זה לזה. ואולי כי לזה רמז באומרו (ויקרא י''ט י''ח) ואהבת לרעך כמוך, פירוש לצד שהוא כמותך כי בשלומו ייטיב לך ובאמצעותו אתה משלים שלימותך ואם כן אינו אחר אלא אתה עצמך וכאחד מחלקיך, ובזה מצאנו נחת רוח כי ה' צוה תרי''ג מצות ומן הנמנע שימצא אדם אחד שישנו בקיום כולם וזה לך האות כהן ולוי וישראל ונשים, יש מצות עשה בכהנים שאין מציאות לישראל לעשותם, ויש מצות לישראל שאינם בכהנים, וכן בלוים, וכן בנשים, ומה מציאות יש ליחיד לקיימם להשלים תיקון לרמ''ח איבריו ושס''ה גידיו אשר יכוונו להם, אלא ודאי שתתקיים התורה במחברת הכללות ויזכו זה מזה, והוא מה שאמר הכתוב כאן **ויעשו בני ישראל ככל אשר צוה ה'** כינה לכולם יחד מעשה כולם הגם שמהם הביאו הנדבה מהם עשו מלאכה יאמר על כללותם שעשו הכל, וסמך מאמר זה למלאכת הבגדים אשר עשאום יחידים מישראל, להעירך כי על פרט זה יאמר שעשאוהו בני ישראל באין הבדל, ומעתה כל אחד מישראל הביא כל הי''ג מינים שבנדבה ועשה כל המלאכות האמורות:
@43 **ככל אשר וגו'**. נתכוין בזה להסיר החשד מהם כי יראה הרואה שצוה ה' על המשכן ונעשה וקפלוהו ג' חדשים (שמו''ר פנ''ב) יאמר כי היתה סיבה מצד המעשה שהיה בו דבר בלתי הגון או שישראל עכבו דבר מכל האמור במצותו, לזה אמר **ותכל** וגו' **ויעשו בני ישראל ככל** ומה טעם המתין הקב''ה עד חדש הראשון שהוא חדש המשובח שנקרא ראשון, והוא אומרו בגמר המלאכה (לקמן מ' ב') ביום החדש הראשון תקים וגו' ורבותינו ז''ל אמרו (שם) לצד שנתבשר אברהם ביצחק:
@43 **אשר צוה וגו** ' **כן עשו**. טעם אומרו **עשו** ולא הספיק במאמר ויעשו, אולי כי העלה עליהם הכתוב שקיימו כל מה שצוה ה' את משה בתורה, וזה שיעור הכתוב **ויעשו בני ישראל ככל** וגו' האמור בענין ובזה העריכם הכתוב כאילו ככל אשר צוה ה' את משה ככל התורה כן עשו, ובזה נשרף ונפזר אפרו של חטא העגל:
@44 **ויביאו את המשכן**. פירוש הזמינוהו לפניו:
@53 **ככל אשר צוה ה'**. וחזר לומר פעם ב' דבר זה וגם בסמוך פעם ג', אולי כי לצד שחטאו בעגל במחשבה ובדיבור ובמעשה וכמו שפירשתי שם ובבחינת כל אחת כפרו בכל התורה כולה, אשר על כן בתיקון היו שלשתם יחד, הנדבה הוא המעשה, המחשבה היא בחינת החכמה שבמלאכה, הדיבור הוא שהיו אומרים בשעת מעשה לשם מצות ה' כמו שפירשתי בקודם, וכנגד שלשתם אמר הכתוב שעשו **כאשר צוה ה' את משה** כי תקנו שלש הדרגות הרע:
@54 **והנה עשו וגו' כן עשו**. טעם שחזר לומר פעם ב' **כן עשו**, כי אומרו והנה עשו נמשכת למעלה וירא וגו' והנה היא עשויה פירוש גוף המעשה, והכוונה בזה שלא היה שיעור בזמן וראה שהנה עשאוהו בזמן מועט.
@54 **עוד** ירצה באומרו **עשו אותה** לשון תיקון שתקנו אותה כמצטרך, ועוד מודיע שהשכיל בה שעשאוה כאשר צוה ה' בפרטי המשפט, והוא אומרו **כאשר** וגו' **כן עשו**.
@54 **עוד** ירצה על פי דבריהם ז''ל (זבחים ס''ב.) כי יש פרטי המצות שאינם לעיכוב אלא למצוה ומנו חכמים דברים המעכבים זה את זה, והודיע הכתוב בכפל המעשה לומר שעשו כל אשר צוה אפילו דברים שאינם אלא למצוה מן המובחר:
@54 **ויברך אותם משה**. טעם שהוצרך לומר **משה** ולא סמך על זכרונו בסמוך, לומר לא תהיה ברכה זו קלה בעיניך כי משה איש האלהים ברכם ודבר גדול הודיע הכתוב בדבר זה, ולטעם זה הוא שהודיע הכתוב ואמר **ויברך אותם** וזולת היות משה אין התורה מגדת אם יברך אדם לחבירו:
@56 **ביום החדש וגו'**. הקמה זו היתה אחר ז' ימי מילואים לדבריהם ז''ל (במד''ר פי''ג), וכן מוכיחים הכתובים כי ז' ימי המילואים לא נעשה בהם אלא מלואי ידי אהרן, ולזה צוה ה' מעשה ז' ימי מילואים קודם מצות הקמת המשכן והערכתו, וגם בפרשת צו כשמשח אהרן ובניו יום א' של מילואים שם הזכיר משיחת המשכן וכליו, ולא הזכיר שם הקמת המשכן וסדרו הא למדת כי המילואים היו קודם הקמת המשכן והערכת כליו, ויום ר''ח ניסן הוא שנתקדש המשכן וסדר משה מערכת המשכן והקריב בו את האמור בענין הא למדת שלא שמש משה במשכן בסדר כל האמור בפרשה זו אלא ביום אחד שהוא יום השמיני של מילואים, ואפילו להסוברים שכל ז' ימי המלואים היה משה בונה משכן וסותרו, בהכרח לומר כי משכן הוא שהיה בונה וסותר אבל סדר הכנתו לא היתה אלא ביום ר''ח ניסן כאמור בענין באחד לחדש וגו' ושמת שם וגו' והבאת את השלחן וגו' הרי כי מחדש הוא מודיעו ההערכה ומקום כל דבר וסדר הנחתו ואם זה לו ז' ימים והוא מעריך מה מקום להודיע מחדש, אלא ודאי זה היום תחלת סדר מעשה המשכן ותיקונו והקריב משה בו ביום כל האמור בענין במצות ה' אליו כאמור לפנינו:
@73 **כאשר צוה ה' את משה**. הוצרך לומר **את משה** ולא הספיק לומר כאשר צוה ה' והדבר ידוע כי אותו צוה ה', כוונת הכתוב הוא להודיע שהתורה מעידה על המעשה שלא היה בו שינוי מהמצוה, ושיעור אומרו כאשר הוא על גופו של מעשה, ואם היה אומר כאשר צוהו ה' היה בנשמע שחוזר על העושה שעשה כאשר צוהו והבן, וטעם כפל הדבר בכל פרט ופרט להראות שכל פרט הוא חשוב מצוה בפני עצמו וראוי ליאמר עליו לבדו צוה ה' את משה:
@89 **ולא יכול משה וגו'**. והגם שאמר הכתוב בפרשת משפטים (כ''ד י''ח) ויבא משה בתוך הענן, שם היה אחר שקרא אליו ה' נתן בו כח. או יאמר על זה הדרך **ולא יכול משה** וגו', והטעם **כי שכן עליו הענן** ואין מציאות זה כמציאות האמור בפרשת משפטים כי כאן.
@89 **כבוד ה' מלא את המשכן** מה שאין כן הענן שבא בו בהר סיני שם נאמר ומראה כבוד ה' כאש אוכלת בראש ההר וסמוך ליה ויבא משה בתוך הענן ויעל אל ההר פירוש מקום שאין שם שוכן כבוד ה' מה שאין כן במה שלפנינו שהיה כבוד ה' מלא המשכן ולא יכול ליכנם במקום מלא כבודו יתברך:
@89 **חסלת פרשת פקודי סליק ספר שמות**
